"use client";

import { useMutation } from "@tanstack/react-query";
import { ArrowLeft, Check, Sparkles } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import { GrammarExercisePlayer } from "@/components/grammar/exercise-player";
import { SlideCard } from "@/components/grammar/slide-card";
import { NotificationPrompt } from "@/components/notification-prompt";
import { Poncha } from "@/components/poncha";
import { Button } from "@/components/ui/button";
import { grammarLessonById, grammarLessons } from "@/lib/content/load";
import type { GrammarExercise } from "@/lib/content/schema";
import { completeGrammarLesson } from "@/lib/db/grammar";
import { XP, recordActivity } from "@/lib/gamification";
import { useAlphabetProgress, useGrammarProgress, useInvalidateLearning, useSupabase, useUser } from "@/lib/queries/hooks";

type Phase =
  | { kind: "slides"; index: number }
  | { kind: "exercises" }
  | { kind: "done"; correct: number; total: number }
  | { kind: "practice"; exercises: GrammarExercise[] }
  | { kind: "practiceDone"; correct: number; total: number; xp: number };

interface PracticeItem {
  id: number;
  exercise: GrammarExercise;
}

export default function GrammarLessonPage() {
  const { lessonId } = useParams<{ lessonId: string }>();
  const router = useRouter();
  const db = useSupabase();
  const { data: user } = useUser();
  const invalidate = useInvalidateLearning();

  const lesson = grammarLessonById(lessonId);
  const [phase, setPhase] = useState<Phase>({ kind: "slides", index: 0 });
  const [practiceError, setPracticeError] = useState(false);
  const [showNotifPrompt, setShowNotifPrompt] = useState(false);

  const { data: alphaProgress } = useAlphabetProgress();
  const { data: grammarProgress } = useGrammarProgress();

  // Practice items already played this session, so "Practice more" again
  // brings fresh ones from the shared pool.
  const seenPracticeIds = useRef<number[]>([]);

  const totalCompleted = 
    (alphaProgress?.filter((u) => u.completed_at)?.length ?? 0) + 
    (grammarProgress?.filter((l) => l.completed_at)?.length ?? 0);

  useEffect(() => {
    if (phase.kind === "done" && totalCompleted === 1 && !localStorage.getItem("hasSeenNotifPrompt")) {
      setShowNotifPrompt(true);
      localStorage.setItem("hasSeenNotifPrompt", "true");
    }
  }, [phase.kind, totalCompleted]);

  const complete = useMutation({
    mutationFn: async ({ correct, total }: { correct: number; total: number }) => {
      if (!user || !lesson) return;
      await completeGrammarLesson(db, user.id, lessonId, correct, total);
      await recordActivity(db, user.id, { xp: XP.grammarLesson });
    },
    onSuccess: () => invalidate(),
  });

  const practice = useMutation({
    mutationFn: async () => {
      const res = await fetch("/api/generate/grammar-practice", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ lessonId, excludeIds: seenPracticeIds.current }),
      });
      if (!res.ok) throw new Error(`Practice generation failed (${res.status})`);
      const data = (await res.json()) as { items: PracticeItem[] };
      if (!data.items?.length) throw new Error("No practice items");
      return data.items;
    },
    onSuccess: (items) => {
      seenPracticeIds.current.push(...items.map((i) => i.id));
      setPracticeError(false);
      setPhase({ kind: "practice", exercises: items.map((i) => i.exercise) });
    },
    onError: () => setPracticeError(true),
  });

  const completePractice = useMutation({
    mutationFn: async (total: number) => {
      if (!user) return 0;
      const xp = XP.review * total;
      await recordActivity(db, user.id, { xp });
      return xp;
    },
    onSuccess: () => invalidate(),
  });

  if (!lesson) {
    return <p className="py-20 text-center text-ink-soft">Lesson not found.</p>;
  }

  const lessonNumber = grammarLessons.findIndex((l) => l.id === lesson.id) + 1;
  const keyExample = lesson.slides[0]?.examples[0];

  return (
    <div className="flex min-h-[calc(100dvh-8.5rem)] flex-col">
      <div className="mb-4 flex items-center gap-3">
        <Link
          href="/grammar"
          className="flex size-9 items-center justify-center rounded-full text-ink-faint transition-colors hover:bg-surface hover:text-ink"
          aria-label="Back to grammar"
        >
          <ArrowLeft size={19} />
        </Link>
        <div>
          <p className="text-[15px] font-semibold leading-tight">
            {lessonNumber}. {lesson.title}
          </p>
          <p className="text-[12px] text-ink-faint">
            {phase.kind === "slides"
              ? `Step ${phase.index + 1} of ${lesson.slides.length}`
              : phase.kind === "exercises"
                ? "Practice"
                : phase.kind === "practice"
                  ? "Extra practice"
                  : "Complete"}
          </p>
        </div>
      </div>

      <AnimatePresence mode="wait">
        {phase.kind === "slides" && (
          <motion.div
            key={`slide-${phase.index}`}
            initial={{ opacity: 0, x: 24 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -18 }}
            transition={{ duration: 0.22, ease: "easeOut" }}
            className="flex flex-1 flex-col"
          >
            <div className="my-auto py-4">
              <SlideCard slide={lesson.slides[phase.index]} />
            </div>
            <div className="pb-6">
              <Button
                size="lg"
                className="w-full"
                onClick={() =>
                  phase.index + 1 < lesson.slides.length
                    ? setPhase({ kind: "slides", index: phase.index + 1 })
                    : setPhase({ kind: "exercises" })
                }
              >
                {phase.index + 1 < lesson.slides.length ? "Next" : "Practice"}
              </Button>
            </div>
          </motion.div>
        )}

        {phase.kind === "exercises" && (
          <motion.div
            key="exercises"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="flex flex-1 flex-col"
          >
            <GrammarExercisePlayer
              exercises={lesson.exercises}
              onComplete={(correct, total) => {
                complete.mutate({ correct, total });
                setPhase({ kind: "done", correct, total });
              }}
            />
          </motion.div>
        )}

        {phase.kind === "practice" && (
          <motion.div
            key="practice"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="flex flex-1 flex-col"
          >
            <GrammarExercisePlayer
              exercises={phase.exercises}
              onComplete={(correct, total) => {
                completePractice
                  .mutateAsync(total)
                  .then((xp) => setPhase({ kind: "practiceDone", correct, total, xp: xp ?? 0 }));
              }}
            />
          </motion.div>
        )}

        {(phase.kind === "done" || phase.kind === "practiceDone") && (
          <motion.div
            key="done"
            initial={{ opacity: 0, scale: 0.97 }}
            animate={{ opacity: 1, scale: 1 }}
            className="flex flex-1 flex-col items-center justify-center text-center"
          >
            <Poncha pose="celebrate" size={140} />
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ type: "spring", stiffness: 400, damping: 22, delay: 0.1 }}
              className="mt-4 flex size-14 items-center justify-center rounded-full bg-sabz-soft text-sabz"
            >
              <Check size={26} strokeWidth={2.5} />
            </motion.div>
            <h2 className="mt-5 text-[22px] font-semibold tracking-tight">
              {phase.kind === "done" ? `${lesson.title} complete` : "Extra practice complete"}
            </h2>
            <p className="mt-2 text-[15px] text-ink-soft">
              {phase.correct} of {phase.total} first try · +
              {phase.kind === "done" ? XP.grammarLesson : phase.xp} XP
            </p>

            {phase.kind === "done" && keyExample && (
              <p
                lang="prs"
                dir="rtl"
                className="mt-6 rounded-full bg-lapis-soft px-5 py-2 text-[20px] text-lapis"
              >
                {keyExample.dari}
              </p>
            )}

            <div className="mt-10 flex flex-col items-center gap-3">
              <Button
                size="lg"
                onClick={() => {
                  router.push("/grammar");
                  router.refresh();
                }}
              >
                Continue
              </Button>
              <Button
                size="lg"
                variant="secondary"
                disabled={practice.isPending}
                onClick={() => practice.mutate()}
              >
                <Sparkles size={17} />
                {practice.isPending ? "Fetching fresh practice…" : "Practice more"}
              </Button>
              {practiceError && (
                <p className="text-[13px] text-ink-faint">
                  Practice isn&apos;t available right now - try again later.
                </p>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <NotificationPrompt isOpen={showNotifPrompt} onClose={() => setShowNotifPrompt(false)} />
    </div>
  );
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { BookOpen } from "lucide-react";
import Link from "next/link";
import { useSupabase, useUser } from "@/lib/queries/hooks";

export default function HistoryPage() {
  const db = useSupabase();
  const { data: user } = useUser();

  const { data: history, isLoading } = useQuery({
    queryKey: ["history", user?.id],
    queryFn: async () => {
      if (!user) return [];

      const { data, error } = await db
        .from("user_texts")
        .select(`
          read_at,
          words_tapped,
          texts (
            id,
            level,
            doc
          )
        `)
        .eq("user_id", user.id)
        .order("read_at", { ascending: false });

      if (error) throw error;
      return data;
    },
    enabled: !!user,
  });

  return (
    <div className="flex flex-col gap-6">
      <header className="pt-2">
        <h1 className="text-[28px] font-semibold tracking-tight">Reading History</h1>
        <p className="mt-1 text-[15px] text-ink-soft">Texts you have completed</p>
      </header>

      {isLoading ? (
        <div className="animate-pulse space-y-4">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-24 rounded-2xl bg-surface/50" />
          ))}
        </div>
      ) : history?.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-center">
          <BookOpen size={48} className="text-line mb-4" />
          <p className="text-[15px] text-ink-soft">You haven't read any texts yet.</p>
        </div>
      ) : (
        <div className="flex flex-col gap-4">
          {history?.map((entry: any, index) => {
            const textData = entry.texts;
            const doc = textData.doc;
            const date = new Date(entry.read_at).toLocaleDateString();

            return (
              <div
                key={`${textData.id}-${index}`}
                className="flex flex-col gap-2 rounded-2xl border border-line bg-surface p-4"
              >
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <h3 lang="prs" className="text-[20px] font-medium leading-snug">
                      {doc.titleDari}
                    </h3>
                    <p className="text-[14px] text-ink-soft mt-0.5">
                      {doc.titleEn}
                    </p>
                  </div>
                  <span className="shrink-0 rounded-full bg-paper px-2.5 py-1 text-[11px] font-medium text-ink-soft border border-line/50">
                    {textData.level}
                  </span>
                </div>

                <div className="mt-2 flex items-center justify-between text-[12px] text-ink-faint">
                  <p>Read on {date}</p>
                  <p>{entry.words_tapped} words explored</p>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { JourneyMap } from "@/components/ui/journey-map";
import { alphabetCourse } from "@/lib/content/load";
import {
  useAlphabetProgress,
  useGrammarProgress,
  useProfile,
} from "@/lib/queries/hooks";

export default function JourneyPage() {
  const { data: profile } = useProfile();
  const { data: alphaProgress } = useAlphabetProgress();
  const { data: grammarProgress } = useGrammarProgress();

  const completedUnits = alphaProgress?.filter((u) => u.completed_at).length ?? 0;
  const totalUnits = alphabetCourse.units.length;

  const completedRows = new Set(
    grammarProgress?.filter((l) => l.completed_at).map((l) => l.lesson_id) ?? []
  );

  return (
    <div className="flex flex-col min-h-[calc(100vh-100px)]">
      <header className="sticky top-0 z-30 flex items-start justify-between p-4 bg-paper/80 backdrop-blur-xl border-b border-line/30 shadow-[0_4px_16px_rgba(31,26,23,0.03)] -mx-4 px-8 pt-6">
        <div>
          <h1 className="text-[26px] font-semibold tracking-tight">Your Journey</h1>
          <p className="text-[14px] text-ink-soft">
            See how far you've come
          </p>
        </div>
      </header>

      <main className="flex-1 w-full relative pt-4 pb-20">
        <JourneyMap
          alphabetCompletedUnits={completedUnits}
          totalAlphabetUnits={totalUnits}
          grammarCompletedLessonIds={completedRows}
          userLevelEstimate={profile?.level_estimate ?? "L1"}
          canReadScript={profile?.can_read_script ?? null}
        />
      </main>
    </div>
  );
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { Medal, Trophy } from "lucide-react";
import { levelLabel } from "@/lib/content/load";
import { useSupabase, useUser } from "@/lib/queries/hooks";

export default function LeaderboardPage() {
  const db = useSupabase();
  const { data: user } = useUser();

  const { data: leaderboard, isLoading } = useQuery({
    queryKey: ["leaderboard"],
    queryFn: async () => {
      const { data, error } = await db
        .from("profiles")
        .select("id, display_name, xp, level_estimate")
        .order("xp", { ascending: false })
        .limit(100);
      if (error) throw error;
      return data;
    },
  });

  return (
    <div className="flex flex-col gap-6">
      <header className="pt-2">
        <h1 className="text-[28px] font-semibold tracking-tight">Leaderboard</h1>
        <p className="mt-1 text-[15px] text-ink-soft">Top learners by total XP</p>
      </header>

      {isLoading ? (
        <div className="animate-pulse space-y-4">
          {[1, 2, 3, 4, 5].map((i) => (
            <div key={i} className="h-16 rounded-2xl bg-surface/50" />
          ))}
        </div>
      ) : (
        <div className="flex flex-col gap-3">
          {leaderboard?.map((profile, index) => {
            const isCurrentUser = profile.id === user?.id;
            const rank = index + 1;

            let rankColor = "text-ink-soft";
            if (rank === 1) rankColor = "text-yellow-500";
            else if (rank === 2) rankColor = "text-slate-400";
            else if (rank === 3) rankColor = "text-amber-700";

            return (
              <div
                key={profile.id}
                className={`flex items-center gap-4 rounded-2xl border p-4 transition-colors ${
                  isCurrentUser ? "border-lapis bg-lapis-soft/50" : "border-line bg-surface"
                }`}
              >
                <div className={`flex w-8 justify-center font-bold ${rankColor}`}>
                  {rank <= 3 ? <Medal size={24} /> : rank}
                </div>

                <div className="flex-1">
                  <p className={`text-[16px] font-medium ${isCurrentUser ? "text-lapis-deep" : ""}`}>
                    {profile.display_name || "Anonymous"}
                  </p>
                  <p className="text-[13px] text-ink-soft">
                    {levelLabel(profile.level_estimate)}
                  </p>
                </div>

                <div className="text-right">
                  <p className="text-[16px] font-semibold text-lapis">{profile.xp}</p>
                  <p className="text-[11px] font-medium uppercase tracking-wider text-ink-faint">XP</p>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

