"use client";

import { ChevronLeft } from "lucide-react";
import Link from "next/link";
import { useAlphabetProgress, useProfile, useUserWords } from "@/lib/queries/hooks";
import { levelLabel, levels } from "@/lib/content/load";
import { VocabChart } from "./vocab-chart";
import { ActivityHeatmap } from "./heatmap";

export default function StatsPage() {
  const { data: profile } = useProfile();
  const { data: words } = useUserWords();
  const { data: alphabet } = useAlphabetProgress();

  if (!profile) return null;

  const totalWords = words?.length ?? 0;
  const knownCount = words?.filter((w) => w.status === "known").length ?? 0;
  const learningCount = words?.filter((w) => w.status === "learning").length ?? 0;

  const completedAlphabetUnits = alphabet?.filter(u => u.completed_at !== null).length ?? 0;

  // Forecast Logic
  const startTimestamp = profile.onboarded_at ? new Date(profile.onboarded_at).getTime() : new Date(profile.created_at).getTime();
  const daysSinceStart = Math.max(1, (Date.now() - startTimestamp) / (1000 * 60 * 60 * 24));
  const wordsPerDay = knownCount / daysSinceStart;

  const currentLevelIdx = levels.findIndex((l) => l.id === profile.level_estimate);
  const nextLevel = currentLevelIdx >= 0 && currentLevelIdx < levels.length - 1 ? levels[currentLevelIdx + 1] : null;
  const wordsToNextLevel = nextLevel ? Math.max(0, nextLevel.entryKnownWords - knownCount) : 0;

  const daysToNextLevel = (wordsPerDay > 0 && nextLevel && wordsToNextLevel > 0) ? Math.ceil(wordsToNextLevel / wordsPerDay) : null;

  let forecastText = "Max level reached!";
  if (nextLevel) {
    if (wordsToNextLevel === 0) {
      forecastText = "Ready for promotion!";
    } else if (daysToNextLevel !== null && daysToNextLevel < 365 * 10) {
      const forecastDate = new Date(Date.now() + daysToNextLevel * 24 * 60 * 60 * 1000);
      const isCurrentYear = forecastDate.getFullYear() === new Date().getFullYear();
      forecastText = `${forecastDate.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: isCurrentYear ? undefined : 'numeric' })} (${daysToNextLevel} day${daysToNextLevel === 1 ? '' : 's'})`;
    } else {
      forecastText = "Learn more words to forecast";
    }
  }

  return (
    <div className="flex flex-col gap-6">
      <header className="flex items-center gap-3 pt-2">
        <Link href="/profile" className="text-ink-soft hover:text-ink transition-colors">
          <ChevronLeft size={24} />
        </Link>
        <h1 className="text-[22px] font-semibold tracking-tight">Your Stats</h1>
      </header>

      <section className="rounded-2xl border border-line bg-surface p-5">
        <h2 className="text-[16px] font-semibold mb-4">Vocabulary Progress</h2>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <p className="text-[28px] font-bold text-lapis">{knownCount}</p>
            <p className="text-[13px] text-ink-soft">Known words</p>
          </div>
          <div>
            <p className="text-[28px] font-bold text-saffron">{learningCount}</p>
            <p className="text-[13px] text-ink-soft">Learning words</p>
          </div>
        </div>
        <VocabChart knownCount={knownCount} learningCount={learningCount} startTimestamp={startTimestamp} />
      </section>

      <section className="grid grid-cols-2 gap-4">
        <div className="rounded-2xl border border-line bg-surface p-5">
          <h2 className="text-[14px] font-medium text-ink-soft mb-1">Total Experience</h2>
          <p className="text-[24px] font-bold">{profile.xp} <span className="text-[14px] font-normal text-ink-soft">XP</span></p>
        </div>
        <div className="rounded-2xl border border-line bg-surface p-5">
          <h2 className="text-[14px] font-medium text-ink-soft mb-1">Alphabet Mastery</h2>
          <p className="text-[24px] font-bold">{completedAlphabetUnits} <span className="text-[14px] font-normal text-ink-soft">units</span></p>
        </div>
      </section>

      <section className="rounded-2xl border border-line bg-surface p-5">
        <h2 className="text-[16px] font-semibold mb-4">Reading Journey</h2>
        <div className="flex flex-col gap-3">
          <div className="flex justify-between items-center">
            <span className="text-[14px] text-ink-soft">Current Level Estimate</span>
            <span className="text-[15px] font-medium px-2 py-0.5 bg-lapis-soft text-lapis rounded-md">
              {levelLabel(profile.level_estimate)}
            </span>
          </div>

          {nextLevel && (
            <div className="flex justify-between items-center">
              <span className="text-[14px] text-ink-soft">Next Level Forecast</span>
              <span className="text-[15px] font-medium text-ink-soft">
                {forecastText}
              </span>
            </div>
          )}

          <div className="flex justify-between items-center">
            <span className="text-[14px] text-ink-soft">Best Streak</span>
            <span className="text-[15px] font-medium">{profile.streak_best} days</span>
          </div>
        </div>
        <ActivityHeatmap />
      </section>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer } from "recharts";

export function VocabChart({ knownCount, learningCount, startTimestamp }: { knownCount: number; learningCount: number, startTimestamp: number }) {
  const [now] = useState(() => Date.now());

  // Generate a beautiful stylized curve from start date to today
  const data = useMemo(() => {
    const points = [];
    const daysSinceStart = Math.max(1, (now - startTimestamp) / (1000 * 60 * 60 * 24));
    const numPoints = Math.min(30, Math.ceil(daysSinceStart));

    for (let i = 0; i <= numPoints; i++) {
      const progress = i / numPoints; // 0 to 1
      // Use an ease-out or S-curve for a natural learning progression look
      const ease = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;

      const date = new Date(startTimestamp + (now - startTimestamp) * progress);
      points.push({
        date: date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
        known: Math.round(knownCount * ease),
        learning: Math.round(learningCount * ease), // Just stylized
      });
    }
    return points;
  }, [knownCount, learningCount, startTimestamp]);

  if (knownCount === 0 && learningCount === 0) return null;

  return (
    <div className="h-48 w-full mt-6">
      <ResponsiveContainer width="100%" height="100%">
        <AreaChart data={data} margin={{ top: 5, right: 0, left: 0, bottom: 5 }}>
          <defs>
            <linearGradient id="colorKnown" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="var(--color-lapis)" stopOpacity={0.4}/>
              <stop offset="95%" stopColor="var(--color-lapis)" stopOpacity={0}/>
            </linearGradient>
            <linearGradient id="colorLearning" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="var(--color-saffron)" stopOpacity={0.4}/>
              <stop offset="95%" stopColor="var(--color-saffron)" stopOpacity={0}/>
            </linearGradient>
          </defs>
          <Tooltip 
            contentStyle={{ backgroundColor: 'var(--color-surface)', border: '1px solid var(--color-line)', borderRadius: '8px' }}
            itemStyle={{ color: 'var(--color-ink)' }}
          />
          <Area 
            type="monotone" 
            dataKey="known" 
            stroke="var(--color-lapis)" 
            strokeWidth={3}
            fillOpacity={1} 
            fill="url(#colorKnown)" 
            animationDuration={1500}
          />
          <Area 
            type="monotone" 
            dataKey="learning" 
            stroke="var(--color-saffron)" 
            strokeWidth={2}
            fillOpacity={1} 
            fill="url(#colorLearning)" 
            animationDuration={1500}
          />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  );
}

"use server";

import { createHash } from "crypto";
import { generateSentenceExplanation, type SentenceExplanation } from "@/lib/ai/explain";
import { supabaseService } from "@/lib/supabase/server";

export async function explainSentence(dari: string): Promise<SentenceExplanation | { error: string }> {
  try {
    const normalized = dari.trim();
    if (!normalized) return { error: "Empty sentence" };

    const hash = createHash("sha256").update(normalized).digest("hex");
    const db = supabaseService();

    // 1. Check cache
    const { data: cached, error: cacheErr } = await db
      .from("sentence_explanations")
      .select("explanation")
      .eq("sentence_hash", hash)
      .single();

    if (!cacheErr && cached?.explanation) {
      return cached.explanation as SentenceExplanation;
    }

    // 2. Generate
    const explanation = await generateSentenceExplanation(normalized);

    // 3. Cache it (fire and forget / await to ensure consistency)
    const { error: insertErr } = await db
      .from("sentence_explanations")
      .upsert({
        sentence_hash: hash,
        explanation: explanation as any,
      });

    if (insertErr) {
      console.error("Failed to cache sentence explanation:", insertErr);
    }

    return explanation;
  } catch (err) {
    console.error("Sentence explanation error:", err);
    return { error: err instanceof Error ? err.message : "Failed to explain sentence" };
  }
}

import { NextResponse } from "next/server";
import webPush from "web-push";
import { supabaseService } from "@/lib/supabase/server";

export async function GET(req: Request) {
  // Verify Vercel Cron authentication
  const authHeader = req.headers.get("Authorization");
  if (authHeader !== `Bearer ${process.env.CRON_SECRET}` && process.env.NODE_ENV === "production") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const supabaseAdmin = supabaseService();

    webPush.setVapidDetails(
      "mailto:admin@darya.app",
      process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY!,
      process.env.VAPID_PRIVATE_KEY!
    );

    // Get users with an active streak but no activity today
    const today = new Date().toISOString().split("T")[0];
    const { data: usersToRemind } = await supabaseAdmin
      .from("profiles")
      .select("id, streak_current, last_active_date")
      .eq("reminder_notifications", true)
      .gt("streak_current", 0)
      .neq("last_active_date", today);

    if (!usersToRemind || usersToRemind.length === 0) {
      return NextResponse.json({ success: true, sent: 0 });
    }

    const userIds = usersToRemind.map((u) => u.id);

    const { data: subscriptions } = await supabaseAdmin
      .from("push_subscriptions")
      .select("*")
      .in("user_id", userIds);

    if (!subscriptions || subscriptions.length === 0) {
      return NextResponse.json({ success: true, sent: 0 });
    }

    let sent = 0;
    const errors: any[] = [];

    await Promise.all(
      subscriptions.map(async (sub) => {
        try {
          await webPush.sendNotification(
            {
              endpoint: sub.endpoint,
              keys: {
                p256dh: sub.p256dh,
                auth: sub.auth,
              },
            },
            JSON.stringify({
              title: "Keep your streak alive! 🔥",
              body: "You haven't practiced Dari today. Do a quick review now to keep your streak going!",
              data: { url: "/" },
            })
          );
          sent++;
        } catch (e: any) {
          if (e.statusCode === 404 || e.statusCode === 410) {
            // Subscription has expired or is no longer valid
            await supabaseAdmin.from("push_subscriptions").delete().eq("id", sub.id);
          } else {
            errors.push(e);
          }
        }
      })
    );

    return NextResponse.json({ success: true, sent, errors });
  } catch (error) {
    console.error("Cron error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { generateReadingSentence } from "@/lib/ai/alphabet-reading";

const requestSchema = z.object({
  knownLetters: z.array(z.string()),
});

export async function POST(req: Request) {
  try {
    const json = await req.json();
    const { knownLetters } = requestSchema.parse(json);

    if (knownLetters.length === 0) {
      return NextResponse.json({ error: "No known letters" }, { status: 400 });
    }

    const sentence = await generateReadingSentence(knownLetters);
    return NextResponse.json(sentence);
  } catch (err: any) {
    console.error("Alphabet Reading generation failed:", err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

